from typing import Dict, Optional

def unit_of_work(metadata: Optional[Dict] = None, timeout: Optional[float] = None):
    def decorator(func):
        def wrapper(tx):
            if timeout is not None and timeout < 0:
                raise ValueError("Timeout cannot be a negative duration")
            if metadata is not None:
                tx.metadata = metadata
            result = func(tx)
            if timeout is not None:
                tx.timeout = timeout
            return result
        return wrapper
    return decorator

