def lfu_cache(maxsize=128, typed=False):
    if not isinstance(maxsize, int) or maxsize < 1:
        raise ValueError("maxsize must be a positive integer")

    from collections import OrderedDict, defaultdict

    class Node:
        def __init__(self, key, value, freq=1):
            self.key = key
            self.value = value
            self.freq = freq

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.key_to_node = {}
            self.freq_to_nodes = defaultdict(OrderedDict)
            self.min_freq = 0

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = (args, tuple(kwargs.items())) if self.typed else args
                if key in self.key_to_node:
                    node = self.key_to_node[key]
                    del self.freq_to_nodes[node.freq][node.key]
                    if not self.freq_to_nodes[node.freq]:
                        del self.freq_to_nodes[node.freq]
                    node.freq += 1
                    self.freq_to_nodes[node.freq][node.key] = node
                    self.min_freq = min(self.min_freq, node.freq)
                    return node.value
                else:
                    result = func(*args, **kwargs)
                    if len(self.key_to_node) >= self.maxsize:
                        _, node_to_delete = self.freq_to_nodes[self.min_freq].popitem(last=False)
                        del self.key_to_node[node_to_delete.key]
                    node = Node(key, result, 1)
                    self.key_to_node[key] = node
                    self.freq_to_nodes[1][key] = node
                    self.min_freq = 1
                    return result
            return wrapper

    return LFUCache(maxsize, typed)

