def _legacy_mergeOrderings(orderings):
    try:
        if not orderings:
            return []

        merged_order = []
        seen = set()

        for ordering in orderings:
            for item in ordering:
                if item not in seen:
                    merged_order.append(item)
                    seen.add(item)

        return merged_order
    except Exception as e:
        return str(e)

