def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    def is_subclass_of(sub, super_):
        if sub == super_:
            return True
        return any(is_subclass_of(s, super_) for s in sub.__bases__)

    def get_minimal_basis(class_list):
        minimal_classes = []
        for cls in class_list:
            if not any(is_subclass_of(c, cls) for c in minimal_classes):
                minimal_classes.append(cls)
        return minimal_classes

    try:
        return get_minimal_basis(classes)
    except (AttributeError, TypeError) as e:
        return f"Error: {e}"

