def _get_err_indices(self, coord_name):
    if(coord_name is None):
        raise ValueError("Coordinate name cannot be None")

    indices = []

    # Assuming there is a dictionary with error indices for each coordinate
    for i, coord in enumerate(self.coords):
        if coord.name == coord_name and self.errors[i] != 0:
