def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    from krake.data.kubernetes import KubernetesManifest, KubernetesResource

    if not isinstance(app, KubernetesManifest):
        raise ValueError("Invalid input: app must be a KubernetesManifest object")

    default_schema = {}
    for resource in app.manifest.resources:
        if not isinstance(resource, KubernetesResource):
            continue

        resource_name = resource.apiVersion + "/" + resource.kind
        if resource_name not in default_schema:
            default_schema[resource_name] = {
                "apiVersion": resource.apiVersion,
                "kind": resource.kind,
                "metadata": resource.metadata,
                "spec": {},
                "status": {},
            }

    return default_schema

