def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]:
    if isinstance(sql, bytes):
        param_search = re.findall(r':\w+', sql.decode)
    else:
        param_search = re.findall(r':\w+', sql)

    if isinstance(params, Sequence):
        params_dict = {f'${i+1}': param for i, param in enumerate(params)}
    elif isinstance(params, dict):
        params_dict = {f'${i+1}': params[key] for i, key in enumerate(sorted(params))}
    else:
        raise TypeError("params must be a dict or Sequence")

    formatted_sql = re.sub(r':\w+', lambda match: params_dict[match.group()], sql)
    if isinstance(sql, bytes):
        formatted_sql = formatted_sql.encode()

    return formatted_sql, params_dict

