def check_digests_present_and_used(manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not manifest_files:
        raise ValueError("Manifest files list is empty")
    if not digests_used:
        raise ValueError("Digests used list is empty")

    missing_digests = []
    unused_digests = set(digests_used)

    for manifest in manifest_files:
        try:
            with open(manifest, 'r') as file:
                content = file.read()
                # Assuming digests are in the format "SHA256:abcd123..."
                digests = [line.split(': ')[0] + ':' for line in content.splitlines() if line.startswith('SHA256:')]
                unused_digests.difference_update(digests)
            for digest in digests:
                if digest not in digests_used:
