import os
import xml.etree.ElementTree as ET

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    packages = {}
    try:
        if not os.path.isdir(folder):
            raise ValueError("The provided folder path does not exist or is not a directory.")

        for root, dirs, files in os.walk(folder):
            for file in files:
                if file.endswith('.xml'):
                    xml_path = os.path.join(root, file)
                    basename = os.path.splitext(file)[0]
                    if basename not in packages:
                        packages[basename] = []
                    try:
                        tree = ET.parse(xml_path)
                        packages[basename].append(tree.getroot())
                    except ET.ParseError:
                        raise ValueError(f"Could not parse XML file: {xml_path}")
    except Exception as e:
        raise Exception(f"An error occurred while exploring the folder: {e}")

    return packages

