def validate_version_inventories(version_dirs):
    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    inventory_records = {}
    root_inventory = None
    misplaced_digests = set()

    for version_dir in version_dirs:
        inventory_path = f"{version_dir}/inventory.txt"
        try:
            with open(inventory_path, 'r') as file:
                inventory = file.read()
                if root_inventory is None:
                    root_inventory = inventory
                else:
                    # Check if the inventory is up to date
                    if inventory != root_inventory:
                        raise ValueError(f"Inconsistent inventory at version {version_dir}")

                # Check content digests
                contents_path = f"{version_dir}/contents.txt"
                with open(contents_path, 'r') as contents_file:
                    contents = contents_file.read()
                    for line in contents.splitlines():
                        content, digest = line.split(' ')
                        root_digest = root_inventory.splitlines()[int(content) - 1].split(' ')[1]
                        if digest != root_digest:
                            misplaced_digests.add((content, digest, root_digest))
        except FileNotFoundError:
            raise FileNotFoundError(f"Inventory file not found for version {version_dir}")
        except Exception as e:
            raise RuntimeError(f"Error processing version {version_dir}: {e}")

    if misplaced_digests:
        raise ValueError(f"Content digests different from those in the root inventory: {misplaced_digests}")

    return inventory_records

