def deep_merge_nodes(nodes):
    from ruamel.yaml import ScalarNode, MappingNode

    result = {}

    for key_node, value_node in nodes:
        if not isinstance(key_node, ScalarNode) or not (isinstance(value_node, MappingNode) or hasattr(value_node, 'value')):
            raise ValueError("Invalid node structure")

        key_value = key_node.value
        if key_value in result:
            if not isinstance(result[key_value], MappingNode):
                result[key_value] = value_node
            else:
                if isinstance(value_node, MappingNode):
                    result[key_value].value.extend(value_node.value)
                else:
                    raise ValueError("Cannot merge non-MappingNode with existing MappingNode")
        else:
            result[key_value] = value_node

