def string_to_int(string: str, alphabet: List[str]) -> int:
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    if not all(isinstance(char, str) and len(char) == 1 for char in alphabet):
        raise ValueError("Alphabet must contain single-character strings")

    alphabet_map = {char: idx for idx, char in enumerate(alphabet)}

    if not all(char in alphabet_map for char in string):
        raise ValueError("String contains characters not in the alphabet")

    base = len(alphabet)
    result = 0

    for char in string:
        result = result * base + alphabet_map[char]

    return result

