import json
import logging
from typing import Dict, List, Tuple, Optional

def load_configurations(config_filenames: List[str], overrides: Optional[Dict[str, str]] = None, resolve_env: bool = True) -> Tuple[Dict[str, Dict], List[logging.LogRecord]]:
    if overrides is None:
        overrides = {}

    log = logging.getLogger(__name__)
    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config_data = json.load(file)
            if resolve_env:
                config_data = resolve_environment_variables(config_data)
            config_dict[filename] = config_data
        except json.JSONDecodeError as e:
            log_records.append(logging.LogRecord(level=logging.ERROR, pathname=filename, msg=str(e), exc_info=exc_info))
        except FileNotFoundError:
            log_records.append(logging.LogRecord(level=logging.ERROR, pathname=filename, msg=f"Config file not found: {filename}", exc_info=exc_info))
        except Exception as e:
            log_records.append(logging.LogRecord(level=logging.ERROR, pathname=filename, msg=f"Unexpected error: {e}", exc_info=exc_info))

    # Apply overrides to the configuration
    for key, value in overrides.items():
        if '.' in key:
            keys = key.split('.')
            current_dict = config_dict
            for k in keys[:-1]:
                current_dict = current_dict.setdefault(k, {})
            current_dict[keys[-1]] = value
        else:
            config_dict[key] = value

    return config_dict, log_records

def resolve_environment_variables(data: dict) -> dict:
    import os
    for key, value in data.items():
        if isinstance(value, dict):
            resolve_environment_variables(value)
        elif isinstance(value, str) and value.startswith('${'):
            env_var = value[2:-1]
            data[key] = os.getenv(env_var, value)
    return data

