def scale(self, other=None):
    if other is None:
        # Return the current scale of the graph
        return self._scale
    elif isinstance(other, (int, float)):
        # Set the new scale of the graph
        if self._scale == 0 or self._scale is None:
            raise LenaValueError("Cannot rescale a graph with unknown or zero scale")
        self._scale = other
        # Rescale all errors with their coordinates
        for field, error in self._errors.items():
            if error:
                scaled_error = [value * (other / self._scale) for value in error]
                self._errors[field] = scaled_error
        # Only rescale the last coordinate
        last_coordinate = self._last_coordinate
        self._last_coordinate = [value * (other / self._scale) for value in last_coordinate]
    else:
        raise ValueError("Invalid input type for scale. Must be a number or None.")

