def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not hist:
        raise ValueError("Histogram cannot be empty")

    if make_value is None:
        make_value = lambda bin_content: bin_content

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("Invalid get_coordinate value")

    if len(field_names) == 1:
        raise ValueError("Number of field names must match the dimension of the result")

    graph_points = []
    for i, bin_content in enumerate(hist.values()):
        if make_value(bin_content) is None:
            continue
        field_values = make_value(bin_content)
        if len(field_values) != len(field_names):
            raise ValueError("Number of field values must match the number of field names")

        if get_coordinate == "left":
            coordinate = hist.bin_edges(i)[0]
        elif get_coordinate == "right":
            coordinate = hist.bin_edges(i)[1]
        elif get_coordinate == "middle":
            coordinate = (hist.bin_edges(i)[0] + hist.bin_edges(i)[1]) / 2

        point = dict(zip(field_names, [coordinate] + list(field_values)))
        graph_points.append(point)

    result = {
        "points": graph_points,
        "scale": hist.scale if scale else "unknown"
    }

    return result

