def verifyObject(iface, candidate, tentative=False):
    from zope.interface import implementedBy, Interface, Invalid

    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"{candidate.__class__.__name__} does not claim to provide {iface}")

    candidate_iface = implementedBy(candidate.__class__)
    if not candidate_iface.providedBy(iface):
        raise Invalid(f"{candidate.__class__.__name__} does not implement the required interface {iface}")

    candidate_methods = {name: attr for name, attr in candidate.__class__.__dict__.items() if callable(attr)}
    required_methods = {name: attr for name, attr in iface.__dict__.items() if callable(attr)}

    missing_methods = required_methods.keys() - candidate_methods.keys()
    if missing_methods:
        raise Invalid(f"{candidate.__class__.__name__} is missing the following methods: {', '.join(missing_methods)}")

    invalid_methods = []
    for name, method in candidate_methods.items():
        if name in required_methods:
            required_method = required_methods[name]
            if not callable(method) or not callable(required_method):
                continue
            if method.__code__ is not required_method.__code__:
                invalid_methods.append(name)

    if invalid_methods:
        if len(invalid_methods) == 1:
            raise Invalid(f"{candidate.__class__.__name__} has an invalid method: {', '.join(invalid_methods)}")
        raise Invalid(f"{candidate.__class__.__name__} has the following invalid methods: {', '.join(invalid_methods)}")

    candidate_attributes = set(candidate.__class__.__dict__.keys())
    required_attributes = set(iface.__dict__.keys())

    missing_attributes = required_attributes - candidate_attributes
    if missing_attributes:
        raise Invalid(f"{candidate.__class__.__name__} is missing the following attributes: {', '.join(missing_attributes)}")

    return True

