def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclass = None
    for base in bases:
        base_m = getattr(base, "__metaclass__", None)
        if base_m is not None:
            if metaclass is None:
                metaclass = base_m
            elif metaclass != base_m:
                raise TypeError("Inconsistent metaclass declarations in bases")

    return metaclass

