import xml.etree.ElementTree as ET

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if not isinstance(node, ET.Element):
        raise ValueError("Input must be an XML element")

    child_dict = {}
    for child in node:
        if child.tag in child_dict:
            raise ValueError(f"Duplicate tag name '{child.tag}' found")
        child_dict[child.tag] = child

    return child_dict

