def _include_groups(self, parser_dict):
    try:
        if 'include' not in parser_dict:
            return

        include_files = parser_dict['include']
        if not isinstance(include_files, list):
            raise ValueError("Include directive must be a list")

        for file_path in include_files:
            if not os.path.exists(file_path):
                raise FileNotFoundError(f"Include file not found: {file_path}")

            with open(file_path, 'r') as file:
                include_content = file.read()
                include_dict = yaml.safe_load(include_content)

            if not isinstance(include_dict, dict):
                raise ValueError("Include file must contain a dictionary")

            self._merge_dicts(parser_dict, include_dict)

    except Exception as e:
        raise Exception(f"Error resolving include groups: {e}")

