import os
import json

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        # Check if the directory exists
        if not os.path.exists(plugin_dir):
            raise ValueError("Plugin directory does not exist")

        # Check if the plugin spec file exists
        spec_file_path = os.path.join(plugin_dir, 'plugin_spec.json')
        if not os.path.exists(spec_file_path):
            raise FileNotFoundError("Plugin spec file not found")

        # Read the plugin spec file
        with open(spec_file_path, 'r') as file:
            spec_data = json.load(file)

        # Flatten the dictionary
        flatten_dict = {}
        def flatten(current_dict, parent_key='', sep='_'):
            for k, v in current_dict.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                if isinstance(v, dict):
                    flatten(v, new_key, sep=sep)
                else:
                    flatten_dict[new_key] = v

        flatten(spec_data)

        return flatten_dict

    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

